<?php if(!$score): ?><section class="panel empty section"><h2>AI đang phân tích hồ sơ</h2><p class="muted">Kết quả sẽ được cập nhật khi quá trình đánh giá hoàn tất.</p></section><?php else: ?>
<div class="grid two section"><section class="panel"><h2><?= ui_icon('sparkles',20) ?> Tổng quan AI Score</h2><div class="analytics-donut" style="--chart-progress:<?= max(0,min(100,(float)$score['overallScore'])) ?>%"><div><strong><?= e($score['overallScore']) ?></strong><span>Điểm phù hợp /100 · <?= e($score['grade']) ?></span></div></div><p><?= e($score['explanation']) ?></p><small class="muted"><?= e($score['modelVersion']) ?> · <?= (int)$score['processingTimeMs'] ?> ms</small></section><section class="panel"><h2>Phân tích tiêu chí</h2><div class="ai-criteria section"><?php foreach(['skillScore'=>'Kỹ năng','experienceScore'=>'Kinh nghiệm','educationScore'=>'Học vấn','otherScore'=>'Khác'] as $k=>$label): ?><div><span class="muted"><?= e($label) ?></span><strong><?= e($score[$k]) ?> <small>/100</small></strong><meter max="100" min="0" value="<?= e($score[$k]) ?>"></meter></div><?php endforeach; ?></div></section></div>
