<div class="grid two section"><section class="panel"><h2>Thông tin đọc được từ CV</h2><p class="muted"><?= e($data['cvFile']['fileName']) ?></p><div class="cv-text-preview"><?= e($data['cvFile']['extractedText']?:'CV chưa có văn bản trích xuất.') ?></div></section><section class="panel"><h2>So khớp CV với mô tả công việc</h2><p class="prose"><?= nl2br(e(strip_tags($data['job']['description']))) ?></p><h3>Kỹ năng yêu cầu</h3><div class="chips"><?php foreach($data['job']['requiredSkills'] as $skill): ?><span><?= e($skill) ?></span><?php endforeach; ?></div></section></div>
